// ─────────────────────────────────────────────────────────────────────────────
// Item U-546 — the four stage-beat formatters, extracted into one module.
//
// WHAT THIS SUITE HAS TO PROVE, AND WHY IN THIS SHAPE.
//
// An extraction's whole claim is that nothing changed. That claim cannot be
// made by reading the diff, and it cannot be made by asserting the new module's
// source text either — item T-573's lesson is that a byte scan outlives its
// subject. So the proof here is a BEFORE/AFTER comparison of the built views:
//
//   `u546-stage-view-baseline.json` was generated by THIS FILE, unchanged,
//   running on `origin/main` at 31641238a1 — the commit before the extraction,
//   where the four private copies were still in place. Nothing in this file
//   imports the extracted module in order to build a view, so it runs on either
//   side of the change and compares like with like.
//
// BOTH BRANCHES OF EACH STAGE'S SIGNAL, per the item, and the branch names mean
// what each stage's own input means by them:
//   • `selection` — `committedValueByLeverKey` undefined (no award fact read)
//     vs a populated map (award read, one lever committed);
//   • `value` — `realizedValueByLeverKey`, the same two states;
//   • `bafo` and `evaluation` carry neither signal. The signal `citedDocFor`
//     reads on those stages IS the citation, so their two branches are the
//     citation unobserved and observed. Stated here rather than left implied,
//     because "both branches" has to name something concrete per stage.
//
// A THIRD BRANCH EXISTS ON TWO STAGES, and it is here because the two-branch
// set left half the population unable to fail. `selection` and `value` build
// their cited row only inside the committed / realized task, so on their
// unobserved branch `citedDocFor` is called and its answer is discarded: the
// prescribed mutation changes nothing a reader can see, and a case asserting
// over that branch would pass mutated and unmutated alike. `observed-uncited`
// is the award or realization read TOGETHER WITH the phantom-only citation map,
// which is the only state on those two stages where a wrong `citedDocFor`
// reaches the surface. `bafo` and `evaluation` need no such branch; they render
// the cited row on every lever that computed.
//
// THE MUTATION THE ITEM PRESCRIBES, and why the fixture is built to catch it.
// `citedDocFor` must read the first CONSUMED fact that has a citation, not the
// first REQUIRED input. Those two differ only when a declared input is absent
// from the facts AND carries a citation AND no consumed fact does. That state is
// reachable: `AMS.ENHANCEMENT_LEAKAGE` declares `term_years`, and
// `AVOIDABLE_SPEND_OVER_TERM` requires only the other two — so the lever
// computes with `term_years` absent, and a citation parked on `term_years`
// describes a document that fed nothing. Every fixture below carries exactly
// that phantom citation, so mutating the shared helper flips a rendered value on
// all four stages rather than on one of them.
// ─────────────────────────────────────────────────────────────────────────────

import fs from 'node:fs';
import path from 'node:path';

import { getSourceArchetype } from '@/lib/source/archetypes/registry';
import { buildLiveStageView } from '@/lib/source/facts/view/stage-analytics-builder';
import type { StageAnalyticsView } from '@/components/source/canvas/analytics/view-model';
import type { FactSourceCitation } from '@/lib/source/facts/fact-types';

const BASELINE_PATH = path.join(__dirname, 'u546-stage-view-baseline.json');

const ams = getSourceArchetype('AMS_MANAGED_SERVICES')!;
const LEAKAGE_KEY = 'AMS.ENHANCEMENT_LEAKAGE';

/**
 * The declared-but-unconsumed input. `AVOIDABLE_SPEND_OVER_TERM` tolerates its
 * absence, so the lever computes without it and it never reaches `evidenceRefs`.
 */
const PHANTOM_KEY = 'term_years';

const PHANTOM_CITATION: FactSourceCitation = {
  doc: 'Term schedule (not consumed by the evaluator)',
  locator: 'Clause 2.1',
};

const CONSUMED_CITATION: FactSourceCitation = {
  doc: 'Change-order register',
  locator: 'Tab 3, row 44',
};

/**
 * Facts that make the leakage lever compute while leaving `term_years` absent,
 * which is the whole point of the fixture.
 */
const FACTS: Record<string, number> = {
  annual_change_order_spend: 4_200_000,
  recurring_avoidable_pct: 18,
};

/** Citations with the phantom only — no consumed fact is cited. */
const CITED_PHANTOM_ONLY: Record<string, FactSourceCitation | null> = {
  [PHANTOM_KEY]: PHANTOM_CITATION,
};

/** The phantom plus a real citation on a fact the evaluator did consume. */
const CITED_PHANTOM_AND_CONSUMED: Record<string, FactSourceCitation | null> = {
  [PHANTOM_KEY]: PHANTOM_CITATION,
  recurring_avoidable_pct: CONSUMED_CITATION,
};

type Branch = 'unobserved' | 'observed' | 'observed-uncited';

interface Fixture {
  /** The stage this view is built for. */
  stage: string;
  /** See the header for what each branch means on each stage. */
  branch: Branch;
}

const FIXTURES: readonly Fixture[] = [
  { stage: 'bafo', branch: 'unobserved' },
  { stage: 'bafo', branch: 'observed' },
  { stage: 'evaluation', branch: 'unobserved' },
  { stage: 'evaluation', branch: 'observed' },
  { stage: 'selection', branch: 'unobserved' },
  { stage: 'selection', branch: 'observed' },
  { stage: 'selection', branch: 'observed-uncited' },
  { stage: 'value', branch: 'unobserved' },
  { stage: 'value', branch: 'observed' },
  { stage: 'value', branch: 'observed-uncited' },
];

/**
 * The branch on which each stage can be shown to read `citedDocFor` wrongly.
 * It has to render a cited row AND have no consumed fact cited, or the case is
 * vacuous. `selection` and `value` build their cited row only inside the
 * committed / realized task, so for them that state needs the award or
 * realization read AND the phantom-only citation map — which is what
 * `observed-uncited` is and why it exists.
 */
const MUTATION_BRANCH: Record<string, Branch> = {
  bafo: 'unobserved',
  evaluation: 'unobserved',
  selection: 'observed-uncited',
  value: 'observed-uncited',
};

const STAGES = [...new Set(FIXTURES.map((f) => f.stage))];

function buildFixture(fixture: Fixture): StageAnalyticsView {
  // The award / realization signal is read on both observed branches; only the
  // citation map differs between them.
  const signalObserved = fixture.branch !== 'unobserved';
  const consumedFactCited = fixture.branch === 'observed';
  const view = buildLiveStageView({
    inputs: FACTS,
    // bafo and evaluation have no award/realization signal, so their observed
    // branch is the citation itself. selection and value get the richer
    // citation map on their observed branch too, so the real-citation path is
    // exercised on all four stages rather than on two.
    citations: consumedFactCited ? CITED_PHANTOM_AND_CONSUMED : CITED_PHANTOM_ONLY,
    archetypeId: ams.id,
    stageKey: fixture.stage,
    baselineLabel: 'Committed value baseline',
    baselineAmount: 12_000_000,
    committedValueByLeverKey:
      fixture.stage === 'selection' && signalObserved
        ? new Map([[LEAKAGE_KEY, 250_000]])
        : undefined,
    realizedValueByLeverKey:
      fixture.stage === 'value' && signalObserved
        ? new Map([[LEAKAGE_KEY, 180_000]])
        : undefined,
  });
  if (!view) {
    throw new Error(
      `fixture ${fixture.stage}/${fixture.branch} built no live view — the ` +
        'leakage lever must compute for this suite to assert anything',
    );
  }
  return view;
}

function buildAll(): Record<string, StageAnalyticsView> {
  const out: Record<string, StageAnalyticsView> = {};
  for (const fixture of FIXTURES) {
    out[`${fixture.stage}/${fixture.branch}`] = buildFixture(fixture);
  }
  return out;
}

// Regenerate the baseline by running this file on the commit BEFORE the
// extraction:  U546_WRITE_BASELINE=1 npx jest --runTestsByPath <this file>
if (process.env.U546_WRITE_BASELINE === '1') {
  fs.writeFileSync(BASELINE_PATH, `${JSON.stringify(buildAll(), null, 2)}\n`);
}

describe('U-546 stage-beat formatter extraction', () => {
  it('has a population to assert over, so no case below passes over an empty set', () => {
    // Population before property. Every assertion in this file is about four
    // stages and eight views; if the fixture list or the archetype emptied,
    // each comparison below would compare nothing with nothing and pass.
    expect(STAGES).toHaveLength(4);
    expect(FIXTURES).toHaveLength(10);
    expect(ams.valueLeverRules!.length).toBeGreaterThan(1);
    expect(fs.existsSync(BASELINE_PATH)).toBe(true);
  });

  it('builds the phantom-citation state the mutation case depends on', () => {
    // If this stops holding, the mutation below becomes a no-op that reads
    // exactly like a caught mutation — the trap item T-724 recorded. So assert
    // the state directly: the lever computes, `term_years` is declared, it is
    // absent from the facts, and it carries a citation.
    const rule = ams.valueLeverRules!.find((r) => r.key === LEAKAGE_KEY)!;
    expect(rule.computation.inputs.map((i) => i.key)).toContain(PHANTOM_KEY);
    expect(FACTS[PHANTOM_KEY]).toBeUndefined();
    expect(CITED_PHANTOM_ONLY[PHANTOM_KEY]?.doc).toBe(PHANTOM_CITATION.doc);
    // And no consumed fact is cited in the unobserved branch, so a helper that
    // read required inputs would have nothing else to return first.
    for (const input of rule.computation.inputs) {
      if (input.key === PHANTOM_KEY) continue;
      expect(CITED_PHANTOM_ONLY[input.key]).toBeUndefined();
    }
  });

  describe('the built view is byte-identical to the pre-extraction baseline', () => {
    const baseline = JSON.parse(fs.readFileSync(BASELINE_PATH, 'utf8')) as Record<
      string,
      unknown
    >;

    it('covers every fixture, so a dropped key cannot pass as agreement', () => {
      // Two errors can cancel into agreement if the comparison is over whatever
      // keys both happen to hold. Assert the key sets match first.
      expect(Object.keys(baseline).sort()).toEqual(
        FIXTURES.map((f) => `${f.stage}/${f.branch}`).sort(),
      );
    });

    it.each(FIXTURES.map((f) => [`${f.stage}/${f.branch}`, f] as const))(
      '%s renders exactly what it rendered before the extraction',
      (key, fixture) => {
        expect(JSON.stringify(buildFixture(fixture), null, 2)).toBe(
          JSON.stringify(baseline[key], null, 2),
        );
      },
    );
  });

  describe('the extracted helper is the one each stage actually renders through', () => {
    // `sharedModule()` is called inside a case rather than at collection time on
    // purpose. On the commit before the extraction the module does not exist, so
    // resolving it at the top of this file would fail every case here including
    // the baseline comparison, and the red-first count would say nothing about
    // what actually changed. Loaded per case, exactly the two cases that are
    // ABOUT the extracted module are red before it and green after.
    function sharedModule() {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      return require('@/lib/source/facts/view/stage-beat-formatters') as {
        usd: (amount: number) => string;
        idSegment: (leverKey: string) => string;
        citedDocFor: unknown;
        targetBandFor: unknown;
        targetLabel: unknown;
      };
    }

    it('exports the four formatters the item names', () => {
      const shared = sharedModule();
      expect(typeof shared.usd).toBe('function');
      expect(typeof shared.idSegment).toBe('function');
      expect(typeof shared.citedDocFor).toBe('function');
      expect(typeof shared.targetBandFor).toBe('function');
      expect(typeof shared.targetLabel).toBe('function');
    });

    it('formats USD and id segments the way the rendered views do', () => {
      const shared = sharedModule();
      expect(shared.usd(4_200_000)).toBe('$4,200,000');
      expect(shared.idSegment(LEAKAGE_KEY)).toBe('ams-enhancement-leakage');
      // Checked against the surface and not only against itself: the id segment
      // the shared helper produces is the one a rendered task id carries.
      expect(
        JSON.stringify(buildFixture({ stage: 'bafo', branch: 'observed' })),
      ).toContain(shared.idSegment(LEAKAGE_KEY));
    });

    // Which branch of which stage can render a citation AT ALL. Measured, not
    // assumed, because the mutation case below is vacuous on any branch that
    // renders no cited row: `selection` and `value` build their cited row only
    // inside the committed / realized task, so with no award or realization
    // read there is nothing on the surface for a wrong `citedDocFor` to spoil.
    // That is a property of those two stages, not a gap in the fixture, and
    // this case is where it is on the record rather than rediscovered.
    const CITED_ROW = 'Cited to';
    const RENDERS_CITED_ROW: Record<string, readonly Branch[]> = {
      bafo: ['unobserved', 'observed'],
      evaluation: ['unobserved', 'observed'],
      selection: ['observed', 'observed-uncited'],
      value: ['observed', 'observed-uncited'],
    };

    it.each(FIXTURES.map((f) => [`${f.stage}/${f.branch}`, f] as const))(
      '%s renders a cited row exactly where this stage is able to',
      (_key, fixture) => {
        const rendered = JSON.stringify(buildFixture(fixture));
        expect(rendered.includes(CITED_ROW)).toBe(
          RENDERS_CITED_ROW[fixture.stage].includes(fixture.branch),
        );
      },
    );

    it('mutates each stage on a branch that renders a cited row, so no case below is vacuous', () => {
      // The guard on the guard. If a stage's mutation branch stopped rendering a
      // cited row, the case below would assert the absence of a string that was
      // never going to be there and would pass under the mutation as well as
      // without it.
      expect(Object.keys(RENDERS_CITED_ROW).sort()).toEqual([...STAGES].sort());
      expect(Object.keys(MUTATION_BRANCH).sort()).toEqual([...STAGES].sort());
      for (const stage of STAGES) {
        expect(RENDERS_CITED_ROW[stage]).toContain(MUTATION_BRANCH[stage]);
        expect(
          JSON.stringify(buildFixture({ stage, branch: MUTATION_BRANCH[stage] })),
        ).toContain(CITED_ROW);
      }
    });

    it.each(STAGES)(
      '%s renders no citation for a lever whose only cited input was never consumed',
      (stage) => {
        // The mutation target, asserted at the destination. `citedDocFor` reading
        // required inputs instead of consumed facts would surface the phantom
        // document here; reading consumed facts surfaces nothing. Serialize the
        // whole view and look for the phantom doc, so the case does not depend on
        // where in each stage's shape the cited value happens to sit.
        const rendered = JSON.stringify(
          buildFixture({ stage, branch: MUTATION_BRANCH[stage] }),
        );
        expect(rendered).not.toContain(PHANTOM_CITATION.doc);
        // And the row IS there, reading as uncited — so the absence above is the
        // helper's answer and not the row's absence.
        expect(rendered).toContain('No citation on the consumed facts');
      },
    );

    it.each(STAGES)(
      '%s renders the consumed fact’s citation when one exists',
      (stage) => {
        // The other direction: a real citation on a fact the evaluator DID
        // consume must reach the surface, so the case above is not passing
        // merely because nothing is ever cited.
        const rendered = JSON.stringify(
          buildFixture({ stage, branch: 'observed' }),
        );
        expect(rendered).toContain(CONSUMED_CITATION.doc);
        expect(rendered).toContain(
          `${CONSUMED_CITATION.doc} · ${CONSUMED_CITATION.locator}`,
        );
      },
    );
  });
});
